var t=`0541-malawah-bread`;var i=`world-0541`;var a=`YE`;var o=`western-asia`;var s=8;var r=46;var d={en:`Malawah Bread`,ua:`Хліб малавах`};var l={en:`A traditional dish from Yemen, centered on all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ємен. Основні складники: пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,430,`g`],[`water`,240,`ml`],[`table-salt`,7,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[[`unsalted-butter`,140,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`honey`,70,`g`]]}];var g={slug:t,id:i,country:`YE`,region:o,servings:8,minutes:46,title:d,text:l,steps:u};export{a as country,g as default,i as id,r as minutes,o as region,s as servings,t as slug,u as steps,l as text,d as title};